return Array.from({ length: 60 }, (_, i) => ({
  json: {
    nome: i + 1
  }
}));

const equipamentos = [
  { nome: "Geladeira", min: 80, max: 400, chance: 100 },
  { nome: "Microondas", min: 800, max: 1500, chance: 15 },
  { nome: "Ar_condicionado", min: 700, max: 2200, chance: 45 },
  { nome: "Televisao", min: 50, max: 200, chance: 65 },
  { nome: "Chuveiro_Eletrico", min: 3500, max: 7500, chance: 20 },
  { nome: "Maquina_de_Lavar", min: 400, max: 1500, chance: 20 },
  { nome: "Computador", min: 100, max: 500, chance: 50 },
  { nome: "Notebook", min: 40, max: 120, chance: 40 },
  { nome: "Ventilador", min: 50, max: 150, chance: 50 },
  { nome: "Lampadas", min: 10, max: 100, chance: 80 },
  { nome: "Ferro_de_Passar", min: 1000, max: 2000, chance: 10 },
  { nome: "Air_Fryer", min: 1200, max: 2000, chance: 15 },
  { nome: "Forno_Eletrico", min: 1000, max: 2500, chance: 10 },
  { nome: "Roteador", min: 5, max: 25, chance: 100 },
  { nome: "Secador_de_Cabelo", min: 1000, max: 2200, chance: 5 }
];

function gerarNumero(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const resultado = {};

equipamentos.forEach(eq => {
  const ligado = Math.random() * 100 < eq.chance;

  resultado[eq.nome] = ligado
    ? gerarNumero(eq.min, eq.max)
    : 0;
});

return [
  {
    json: resultado
  }
];

const items = $input.all();

const totalItems = items.length;

if (totalItems === 0) {
  return [];
}

// Soma os valores de cada equipamento
const somas = {};

for (const item of items) {
  const dados = item.json;

  for (const [equipamento, valor] of Object.entries(dados)) {
    somas[equipamento] = (somas[equipamento] || 0) + (Number(valor) || 0);
  }
}

// Calcula a média de cada equipamento
const medias = {};

for (const [equipamento, soma] of Object.entries(somas)) {
  medias[equipamento] = Number((soma / totalItems).toFixed(2));
}

// Retorna um único JSON com todas as médias
return [
  {
    json: {
      total_analisado: totalItems,
      medias
    }
  }
];

const items = $input.all();

// Potência de referência de cada aparelho (Watts)
const referencias = {
  Geladeira: 150,
  Microondas: 1000,
  Ar_condicionado: 1000,
  Televisao: 100,
  Chuveiro_Eletrico: 5000,
  Maquina_de_Lavar: 800,
  Computador: 200,
  Notebook: 60,
  Ventilador: 80,
  Lampadas: 15,
  Ferro_de_Passar: 1200,
  Air_Fryer: 1400,
  Forno_Eletrico: 1500,
  Roteador: 15,
  Secador_de_Cabelo: 1500
};

const resultados = [];

for (const item of items) {
  const dados = item.json.medias;

  for (const [aparelho, consumo] of Object.entries(dados)) {

    const referencia = referencias[aparelho];

    if (referencia === undefined) continue;

    // Diferença em relação à referência
    const diferenca = Number((consumo - referencia).toFixed(2));

    // Classificação do consumo
    let status;

    if (consumo <= referencia * 0.8) {
      status = "Baixo";
    } else if (consumo <= referencia) {
      status = "Moderado";
    } else {
      status = "Alto";
    }

    resultados.push({
      json: {
        aparelho: aparelho,
        consumo_medio: consumo,
        consumo_referencia: referencia,
        status: status,
        diferenca_media: diferenca,
        percentual_referencia: Number(
          ((consumo / referencia) * 100).toFixed(2)
        )
      }
    });
  }
}

return resultados;

// Pega todos os itens que chegam ao nó
const incomingItems = $input.all();

// Normaliza para lidar tanto com itens separados quanto com um array único empacotado
let items = [];
if (incomingItems.length === 1 && Array.isArray(incomingItems[0].json)) {
  items = incomingItems[0].json;
} else if (incomingItems.length === 1 && incomingItems[0].json.aparelhos) {
  items = incomingItems[0].json.aparelhos;
} else {
  items = incomingItems.map(i => i.json);
}

// Filtra apenas aparelhos com consumo Moderado ou Alto (ignorando maiúsculas/minúsculas para segurança)
const aparelhosFiltrados = items
  .filter(item => {
    const status = (item["Status"] || "").trim().toLowerCase();
    return status === "moderado" || status === "alto";
  })
  .map(item => ({
    aparelho: item["Aparelho"],
    consumo_medio: item["Consumo medio"],
    media_referencia: item["Media geral"],
    status: item["Status"],
    diferenca_media: item["Diferenca media"],
    data: item["Data"],
    hora: item["Hora"]
  }));

// Retorna o objeto unificado pronto para a IA
return [{
  json: {
    total_aparelhos_analisados: items.length,
    total_aparelhos_filtrados: aparelhosFiltrados.length,
    aparelhos: aparelhosFiltrados
  }
}];

const dados = $input.first().json;

// Extrai o texto gerado pelo AI Agent
const texto = dados.output?.[0]?.content?.find(
  item => item.type === "output_text"
)?.text || "";

// Separa as partes usando as quebras de linha
const partes = texto.trim().split(/\n+/);

// Primeira parte: decisão
const decisao = partes[0]?.trim() || "";

// Localiza o assunto
const indiceAssunto = partes.findIndex(
  linha => /^Assunto:/i.test(linha.trim())
);

// Extrai o assunto
const assunto = indiceAssunto >= 0
  ? partes[indiceAssunto].replace(/^Assunto:\s*/i, "").trim()
  : "";

// Extrai o corpo após o assunto
const corpoEmail = indiceAssunto >= 0
  ? partes.slice(indiceAssunto + 1).join("\n").trim()
  : "";

return [
  {
    json: {
      decisao,
      enviar_email: /^Enviar email$/i.test(decisao),
      assunto,
      corpo_email: corpoEmail
    }
  }
];
